package com.xdownload.mobile;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
/** A bounded, persistent, dynamically split partition. All range changes and writes share one monitor. */
final class DynamicRanges{
 static final int MAX_PARTS=128;static final long MIN_TAIL=1024L*1024;
 static final class Piece{final int id;final long begin;long end,done;boolean busy;Piece(int id,long begin,long end,long done){this.id=id;this.begin=begin;this.end=end;this.done=done;}long remaining(){return end-begin-done;}}
 static long splitPoint(long begin,long end,long done){long left=end-begin-done;if(left<2*MIN_TAIL)return -1;return begin+done+left/2;}
 static boolean hasLayout(File f){try(InputStream in=new FileInputStream(ParallelEngine.meta(f))){Properties p=new Properties();p.load(in);return "2".equals(p.getProperty("layout"));}catch(Exception ex){return false;}}
 static final class Layout{
  final File target;final HttpEngine.Info info;final String url;final ArrayList<Piece> parts=new ArrayList<>();final AtomicLong total=new AtomicLong();
  Layout(File target,HttpEngine.Info info,String url){this.target=target;this.info=info;this.url=url;}
  void init(int workers)throws IOException{boolean loaded=false;try(InputStream in=new FileInputStream(ParallelEngine.meta(target))){Properties p=new Properties();p.load(in);int n=Integer.parseInt(p.getProperty("parts","0"));if(n<2||n>MAX_PARTS||!url.equals(p.getProperty("url"))||!info.etag.equals(p.getProperty("etag"))||!Long.toString(info.size).equals(p.getProperty("size")))throw new IOException("Stale checkpoint");boolean dynamic="2".equals(p.getProperty("layout"));if(!dynamic&&n>32)throw new IOException("Invalid legacy checkpoint");for(int i=0;i<n;i++){long a=dynamic?Long.parseLong(p.getProperty("begin."+i)):ParallelEngine.boundary(info.size,i,n),b=dynamic?Long.parseLong(p.getProperty("end."+i)):ParallelEngine.boundary(info.size,i+1,n);File f=ParallelEngine.segment(target,i);long done=f.length();if(a<0||b<=a||b>info.size||done>b-a)throw new IOException("Invalid checkpoint range");parts.add(new Piece(i,a,b,done));}validate();loaded=true;}catch(Exception ex){parts.clear();}if(!loaded){ParallelEngine.clear(target);int n=Math.max(2,Math.min(32,workers));for(int i=0;i<n;i++)parts.add(new Piece(i,ParallelEngine.boundary(info.size,i,n),ParallelEngine.boundary(info.size,i+1,n),0));}for(Piece p:parts)total.addAndGet(p.done);save();}
  ArrayList<Piece> ordered(){ArrayList<Piece> list=new ArrayList<>(parts);list.sort(Comparator.comparingLong(p->p.begin));return list;}
  void validate()throws IOException{long pos=0;for(Piece p:ordered()){if(p.begin!=pos||p.end<=p.begin||p.done<0||p.done>p.end-p.begin)throw new IOException("Invalid range partition");pos=p.end;}if(pos!=info.size)throw new IOException("Incomplete range partition");}
  void save()throws IOException{validate();Properties p=new Properties();p.setProperty("layout","2");p.setProperty("url",url);p.setProperty("etag",info.etag);p.setProperty("size",Long.toString(info.size));p.setProperty("parts",Integer.toString(parts.size()));for(Piece item:parts){p.setProperty("begin."+item.id,Long.toString(item.begin));p.setProperty("end."+item.id,Long.toString(item.end));}File meta=ParallelEngine.meta(target),tmp=new File(meta.getPath()+".tmp");try(FileOutputStream out=new FileOutputStream(tmp)){p.store(out,null);out.getFD().sync();}if(!tmp.renameTo(meta))throw new IOException("Cannot save dynamic checkpoint");}
  synchronized Piece claim(boolean allowSplit)throws IOException{Piece best=null;for(Piece p:parts)if(!p.busy&&p.remaining()>0&&(best==null||p.remaining()>best.remaining()))best=p;if(best!=null){best.busy=true;return best;}if(!allowSplit||parts.size()>=MAX_PARTS)return null;for(Piece p:parts)if(p.busy&&splitPoint(p.begin,p.end,p.done)>0&&(best==null||p.remaining()>best.remaining()))best=p;if(best==null)return null;long old=best.end,cut=splitPoint(best.begin,best.end,best.done);Piece child=new Piece(parts.size(),cut,old,0);best.end=cut;parts.add(child);try{save();}catch(IOException e){parts.remove(parts.size()-1);best.end=old;throw e;}child.busy=true;return child;}
 }
 static final class Invalid extends IOException{Invalid(String message){super(message);}}
 static long transfer(String url,boolean http,File target,HttpEngine.Observer observer,int requested)throws IOException{
  HttpEngine.Info info=HttpEngine.probe(url,http);if(!info.ranges||info.size<4*1024*1024L||info.etag.isEmpty()||info.etag.startsWith("W/")||target.length()!=0||HttpEngine.html(info.mime)||HttpEngine.manifest(info.name,info.mime)){ParallelEngine.clear(target);return HttpEngine.download(url,http,target,"","",observer,0);}
  int workers=Math.max(1,Math.min(32,requested));Layout layout=new Layout(target,info,url);layout.init(workers);AtomicBoolean abort=new AtomicBoolean();ExecutorService pool=Executors.newFixedThreadPool(workers);ArrayList<Future<?>> jobs=new ArrayList<>();boolean success=false,invalid=false;
  try{observer.progress(layout.total.get(),info.size,info.etag,info.modified);
   for(int i=0;i<workers;i++)jobs.add(pool.submit(()->{while(!abort.get()&&observer.proceed()){Piece p=layout.claim(workers>1);if(p==null)return null;try{fetch(layout,p,http,observer,abort);}finally{synchronized(layout){p.busy=false;}}}return null;}));
   while(true){boolean done=true;for(Future<?> job:jobs){if(job.isDone())job.get();else done=false;}observer.progress(layout.total.get(),info.size,info.etag,info.modified);if(!observer.proceed()){abort.set(true);return -1;}if(done)break;Thread.sleep(200);}
   layout.validate();try(FileOutputStream out=new FileOutputStream(target)){byte[] buf=new byte[65536];for(Piece p:layout.ordered()){File f=ParallelEngine.segment(target,p.id);if(f.length()!=p.end-p.begin)throw new IOException("Range incomplete");try(InputStream in=new FileInputStream(f)){int n;while((n=in.read(buf))!=-1){if(!observer.proceed())return -1;out.write(buf,0,n);}}}out.getFD().sync();}if(target.length()!=info.size)throw new IOException("Combined size mismatch");success=true;return info.size;
  }catch(ExecutionException e){invalid=e.getCause() instanceof Invalid;throw new IOException(invalid?e.getCause().getMessage():"Dynamic range transfer interrupted: "+e.getCause().getMessage(),e);}catch(InterruptedException e){Thread.currentThread().interrupt();return -1;}finally{abort.set(true);pool.shutdownNow();boolean stopped=false;try{stopped=pool.awaitTermination(40,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}if(!success)target.delete();if(stopped&&(success||invalid))ParallelEngine.clear(target);if(!stopped)ParallelEngine.meta(target).delete();}
 }
 static void fetch(Layout layout,Piece p,boolean http,HttpEngine.Observer observer,AtomicBoolean abort)throws IOException{long start,end;synchronized(layout){start=p.begin+p.done;end=p.end-1;}if(start>end)return;HttpURLConnection c=HttpEngine.connectRange(layout.url,http,"GET",start,end,layout.info.etag);try{int status=c.getResponseCode();if(status==429||status==403||status==401||status==404||status==410)throw new IOException("HTTP "+status);String expected="bytes "+start+"-"+end+"/"+layout.info.size;if(status!=206||!expected.equals(c.getHeaderField("Content-Range"))||!layout.info.etag.equals(c.getHeaderField("ETag"))||HttpEngine.html(HttpEngine.str(c.getContentType()))||!identity(c.getHeaderField("Content-Encoding")))throw new Invalid("Server did not honor validated dynamic range");try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(ParallelEngine.segment(layout.target,p.id),true)){byte[] buffer=new byte[65536];long received=0;while(!abort.get()&&observer.proceed()){int want;synchronized(layout){want=(int)Math.min(buffer.length,p.remaining());}if(want<=0)break;int n=in.read(buffer,0,want);if(n<0)break;received+=n;if(received>end-start+1)throw new Invalid("Response exceeded validated range");if(!observer.throttle(n)){abort.set(true);break;}synchronized(layout){int write=(int)Math.min(n,p.remaining());if(write>0){out.write(buffer,0,write);p.done+=write;layout.total.addAndGet(write);}}}out.getFD().sync();synchronized(layout){if(!abort.get()&&observer.proceed()&&p.remaining()!=0)throw new IOException("Range incomplete");}}}finally{c.disconnect();}}
 static boolean identity(String encoding){return encoding==null||encoding.isEmpty()||"identity".equalsIgnoreCase(encoding);}
}